/**
 * Minimal TTL + LRU cache used to shield the GitHub API from the bursty
 * traffic generated by README renders.
 *
 * Serverless instances are short-lived, so the cache is a best-effort
 * optimisation rather than a correctness requirement; it is therefore
 * dependency-free and synchronous. Recency is tracked through `Map` insertion
 * order: a hit re-inserts the key, so eviction is least-recently-used.
 */
export class TtlCache {
    /**
     * @param {object} options Cache configuration.
     * @param {number} options.ttlMs Entry lifetime in milliseconds.
     * @param {number} options.maxEntries Hard upper bound on entry count.
     * @param {number} [options.now] Injectable clock, for deterministic tests.
     */
    constructor({ ttlMs, maxEntries, now = Date.now }) {
        if (!(ttlMs > 0) || !(maxEntries > 0)) {
            throw new RangeError('TtlCache requires a positive ttlMs and maxEntries.');
        }
        this.ttlMs = ttlMs;
        this.maxEntries = maxEntries;
        this.now = now;
        this.entries = new Map();
    }

    get size() {
        return this.entries.size;
    }

    /** Return the cached value, or `undefined` when absent or expired. */
    get(key) {
        const entry = this.entries.get(key);
        if (!entry) return undefined;
        if (this.now() - entry.storedAt >= this.ttlMs) {
            this.entries.delete(key);
            return undefined;
        }
        // Refresh recency.
        this.entries.delete(key);
        this.entries.set(key, entry);
        return entry.value;
    }

    set(key, value) {
        this.entries.delete(key);
        this.entries.set(key, { value, storedAt: this.now() });
        this.prune();
        return value;
    }

    /** Drop expired entries first, then evict the least recently used ones. */
    prune() {
        const now = this.now();
        for (const [key, entry] of this.entries) {
            if (now - entry.storedAt >= this.ttlMs) this.entries.delete(key);
        }
        while (this.entries.size > this.maxEntries) {
            this.entries.delete(this.entries.keys().next().value);
        }
    }

    clear() {
        this.entries.clear();
    }
}
